/**
 * The baked London timetable: pure decode of the committed artifact bytes.
 *
 * The artifact is generated by scripts/lupt/generate.mjs from the publisher's
 * own workbooks (2027-2076) and the captured API year 2026: a 12-byte header
 * then 18,628 day-major rows of six little-endian uint16 minutes-from-midnight
 * in canonical order. This module holds no clock and no IO, so every behaviour
 * is testable by construction.
 *
 * A record built here is byte-for-byte what the download pipeline used to
 * store: derived Suhoor, Duha and Istijaba are worked out the same way
 * transformApiData worked them out, from the day's own six times.
 */

const MAGIC = 'LUPT';
const FORMAT_VERSION = 1;
export const HEADER_BYTES = 12;

/** Days from 1970-01-01 to 2026-01-01, the artifact's first day */
export const EPOCH_DAY = 20_454;
/** 2026-01-01 to 2076-12-31 inclusive: 365 + 50 years with 13 leap days */
export const DAY_COUNT = 18_628;
const _FIRST_DAY = '2026-01-01';
const _LAST_DAY = '2076-12-31';

/** The six provider times in artifact column order */
export const COLUMNS = ['fajr', 'sunrise', 'dhuhr', 'asr', 'magrib', 'isha'] as const;

/** Never a minute: the sentinel for a time the publisher did not publish */
export const NULL_MINUTE = 0xffff;

export interface TimetableHeader {
  epochDay: number;
  dayCount: number;
  columns: number;
}

export type DayMinutes = {
  [Column in (typeof COLUMNS)[number]]: number | null;
};

/**
 * Validates the whole buffer against this build's expectations, or returns null.
 *
 * Torn or foreign bytes must read as absent rather than as times (T-541's
 * lesson), so every check is exact: magic, format version, the span this build
 * was generated for, and the length its own counts imply.
 */
export const decodeTimetableHeader = (bytes: Uint8Array): TimetableHeader | null => {
  if (bytes.length < HEADER_BYTES) return null;
  if (String.fromCharCode(bytes[0], bytes[1], bytes[2], bytes[3]) !== MAGIC) return null;
  if (readUint16(bytes, 4) !== FORMAT_VERSION) return null;

  const epochDay = readUint16(bytes, 6);
  const dayCount = readUint16(bytes, 8);
  const columns = readUint16(bytes, 10);
  if (epochDay !== EPOCH_DAY || dayCount !== DAY_COUNT || columns !== COLUMNS.length) return null;

  if (bytes.length !== HEADER_BYTES + dayCount * columns * 2) return null;
  return { epochDay, dayCount, columns };
};

const readUint16 = (bytes: Uint8Array, offset: number): number => bytes[offset]! + bytes[offset + 1]! * 0x100;

/**
 * A date's row index, or null outside the span or for a date that does not exist.
 *
 * Date.UTC auto-rolls a nonexistent date (2027-02-29 to 2027-03-01), so the
 * string is rebuilt from the instant and compared before the index is trusted.
 */
export const dayIndex = (date: string): number | null => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  const instant = Date.parse(`${date}T00:00:00Z`);
  if (Number.isNaN(instant)) return null;
  const index = Math.floor(instant / 86_400_000) - EPOCH_DAY;
  if (index < 0 || index >= DAY_COUNT) return null;
  const roundTrip = new Date((index + EPOCH_DAY) * 86_400_000).toISOString().slice(0, 10);
  return roundTrip === date ? index : null;
};

/**
 * One day's six minutes in column order, null where the sentinel stands. The
 * index comes from dayIndex, which owns the span's bounds.
 */
export const readDayMinutes = (bytes: Uint8Array, header: TimetableHeader, index: number): (number | null)[] => {
  const offset = HEADER_BYTES + index * header.columns * 2;
  const minutes: (number | null)[] = [];
  for (let column = 0; column < header.columns; column += 1) {
    const minute = readUint16(bytes, offset + column * 2);
    minutes.push(minute === NULL_MINUTE ? null : minute);
  }
  return minutes;
};

const minuteToTimeString = (minute: number): string =>
  `${String(Math.floor(minute / 60)).padStart(2, '0')}:${String(minute % 60).padStart(2, '0')}`;

/** Modular clock arithmetic on minutes, the same wrap adjustTime applies to strings */
const derivedMinute = (minute: number, adjustment: number): string =>
  minuteToTimeString((((minute + adjustment) % 1440) + 1440) % 1440);

/**
 * The day as the app reads it: six published times plus the three derived
 * extras, each null when the time it comes from is (shared/types.ts contract).
 *
 * Istijaba is derived for every day, as transformApiData did: which days show
 * it is a list-building question, never a storage one.
 */
export const minutesToRecord = (date: string, minutes: DayMinutes) => ({
  date,
  fajr: minutes.fajr === null ? null : minuteToTimeString(minutes.fajr),
  sunrise: minutes.sunrise === null ? null : minuteToTimeString(minutes.sunrise),
  dhuhr: minutes.dhuhr === null ? null : minuteToTimeString(minutes.dhuhr),
  asr: minutes.asr === null ? null : minuteToTimeString(minutes.asr),
  magrib: minutes.magrib === null ? null : minuteToTimeString(minutes.magrib),
  isha: minutes.isha === null ? null : minuteToTimeString(minutes.isha),
  suhoor: minutes.fajr === null ? null : derivedMinute(minutes.fajr, -20),
  duha: minutes.sunrise === null ? null : derivedMinute(minutes.sunrise, 20),
  istijaba: minutes.magrib === null ? null : derivedMinute(minutes.magrib, -60),
});
